ee:variables.ee:set-variable:
%dw 2.0
import dw::Crypto
output text/plain
---
// Null-safe: if rawBody is absent (e.g. an MUnit or caller that did not pass through
// the main flow), skip HMAC and return "" so the signature branch is a no-match and the
// X-CD-Token fallback authenticates. Real callbacks always carry rawBody.
if (vars.rawBody != null)
    "sha256=" ++ Crypto::HMACWith(p('secure::github.webhookSecret') as Binary, vars.rawBody as Binary, "HmacSHA256")
else ""
